package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

/** Lifecycle/authority fixtures; the separate Electron study observes real rendered results. */
public class ChatArchive112Test {
    static JSONObject request(Agency043 agency,String... ids){return new JSONObject().put("planSha256",agency.history112().getString("planSha256")).put("ids",new JSONArray(Arrays.asList(ids)));}
    static String inspect(Agency043Test.Fixture f)throws Exception{var task=f.start("Inspect labelled lifecycle fixture","inspect");f.agency.tick();f.acknowledge(f.claim(),new JSONObject());var claim=f.claim();f.acknowledge(claim,f.proof(claim,claim.getJSONObject("extra").getJSONArray("steps")));assertEquals("completed",f.agency.read(task.getString("id")).getString("status"));return task.getString("id");}
    static Agency043 reopen(Agency043Test.Fixture f)throws Exception{f.agency.close();return new Agency043(f.root,f.store,f.learning,r->{throw new AssertionError("No model in cold history check");},id->{},(k,d)->{},()->false,false);}
    static Path archive(Agency043Test.Fixture f,String id){return f.root.resolve("agency-043/archive112/"+f.agency.read(id).getJSONObject("archive112").getString("snapshotSha256")+".json");}
    static JSONObject original(JSONObject g){var copy=WorldFrames.copy(g);copy.remove("archive112");return copy;}
    @Test public void exactCheckpointAndTaskJournalSurviveColdLookup()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);var before=f.agency.read(id);var outcomes=f.agency.outcomes();byte[] bytes=Files.readAllBytes(f.root.resolve("agency-043/tasks.json"));var receipt=f.agency.archive112(request(f.agency,id));assertEquals(0,receipt.getInt("active"));assertEquals(1,receipt.getInt("archived"));assertEquals(24,receipt.getInt("limit"));assertArrayEquals(bytes,Files.readAllBytes(archive(f,id)));assertTrue(before.similar(original(f.agency.read(id))));assertTrue(outcomes.similar(f.agency.outcomes()));assertTrue(f.agency.verify112(id).getBoolean("passed"));f.agency=reopen(f);assertTrue(before.similar(original(f.agency.read(id))));assertTrue(f.agency.verify112(id).getBoolean("passed"));assertEquals(0,f.agency.state().getJSONArray("tasks").length());}
    }
    @Test public void unverifiedConversationStaysUnverifiedAndLimitRemains24()throws Exception{
        try(var f=new Agency043Test.Fixture(r->Agency043Test.reply("finish",new JSONObject().put("summary","A descriptive answer only")))){var task=f.start("Summarize information","workbench");f.agency.tick();f.acknowledge(f.claim(),new JSONObject());f.agency.tick();String id=task.getString("id");assertEquals("completed-unverified",f.agency.read(id).getString("outcome"));f.agency.archive112(request(f.agency,id));assertEquals("completed-unverified",f.agency.verify112(id).getString("outcome"));assertEquals("completed-unverified",f.agency.outcomes().getJSONObject(0).getString("status"));for(int i=0;i<24;i++){var g=f.start("Inspect pending "+i,"inspect");f.agency.control(g.getString("id"),"cancel");}assertEquals(24,f.agency.history112().getInt("active"));assertEquals(1,f.agency.history112().getInt("archived"));assertEquals(0,f.agency.history112().getInt("eligible"));assertThrows(IllegalStateException.class,()->f.start("Inspect over capacity","inspect"));}
    }
    @Test public void selectedTasksLeaveCancelledAndInterruptedRecordsUntouched()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);var stopped=f.start("Inspect stopped","inspect");f.agency.control(stopped.getString("id"),"cancel");var unfinished=f.start("Inspect resumable","inspect");f.agency.tick();f.claim();f.agency.detach(f.session);var stoppedBefore=f.agency.read(stopped.getString("id"));var unfinishedBefore=f.agency.read(unfinished.getString("id"));f.agency.archive112(request(f.agency,id));assertTrue(stoppedBefore.similar(f.agency.read(stopped.getString("id"))));assertTrue(unfinishedBefore.similar(f.agency.read(unfinished.getString("id"))));assertEquals(2,f.agency.history112().getInt("active"));assertThrows(IllegalStateException.class,()->f.agency.archive112(request(f.agency,unfinished.getString("id"))));f.agency.control(unfinished.getString("id"),"resume");assertEquals("queued",f.agency.read(unfinished.getString("id")).getString("status"));}
    }
    @Test public void staleDuplicateUnknownAndActiveRequestsDoNotChangeCheckpoint()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);var in=request(f.agency,id);byte[] bytes=Files.readAllBytes(f.root.resolve("agency-043/tasks.json"));assertThrows(IllegalStateException.class,()->f.agency.archive112(WorldFrames.copy(in).put("planSha256","0".repeat(64))));assertThrows(IllegalArgumentException.class,()->f.agency.archive112(request(f.agency,id,id)));assertThrows(IllegalArgumentException.class,()->f.agency.archive112(request(f.agency,UUID.randomUUID().toString())));assertThrows(IllegalArgumentException.class,()->f.agency.archive112(WorldFrames.copy(in).put("force",true)));assertArrayEquals(bytes,Files.readAllBytes(f.root.resolve("agency-043/tasks.json")));f.agency.archive112(in);assertThrows(IllegalStateException.class,()->f.agency.archive112(in));var live=f.start("Inspect active","inspect");assertThrows(IllegalStateException.class,()->f.agency.archive112(request(f.agency,live.getString("id"))));}
    }
    @Test public void archivedTasksCannotResumeCancelOrReceiveOldEffects()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);f.agency.archive112(request(f.agency,id));var before=f.agency.read(id);for(String action:List.of("resume","cancel"))assertThrows(IllegalStateException.class,()->f.agency.control(id,action));assertThrows(IllegalStateException.class,()->f.agency.requireExecution(id,UUID.randomUUID().toString()));assertThrows(IllegalStateException.class,()->f.agency.abort(new JSONObject().put("taskId",id).put("effectId",UUID.randomUUID().toString()).put("nonce",UUID.randomUUID().toString()).put("sessionId",f.session).put("error","late")));assertTrue(before.similar(f.agency.read(id)));}
    }
    @Test public void corruptMissingAndNonFileSnapshotsRefuseWithoutChangingCheckpoint()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);f.agency.archive112(request(f.agency,id));Path file=archive(f,id);byte[] original=Files.readAllBytes(file),checkpoint=Files.readAllBytes(f.root.resolve("agency-043/tasks.json"));byte[] changed=original.clone();changed[changed.length-2]^=1;Files.write(file,changed);assertThrows(IllegalStateException.class,()->f.agency.read(id));assertThrows(IllegalStateException.class,()->f.agency.verify112(id));Files.write(file,original);Files.delete(file);assertThrows(IllegalStateException.class,()->f.agency.read(id));Files.createDirectory(file);assertThrows(IllegalStateException.class,()->f.agency.read(id));Files.delete(file);Files.write(file,original);assertArrayEquals(checkpoint,Files.readAllBytes(f.root.resolve("agency-043/tasks.json")));assertTrue(f.agency.verify112(id).getBoolean("passed"));}
    }
    @Test public void revisedOriginalReportRefusesBeforeAndAfterArchive()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);f.agency.archive112(request(f.agency,id));var report=f.agency.read(id).getJSONObject("report");f.store.write(new JSONObject().put("id",report.getString("id")).put("expectedVersion",report.getInt("version")).put("title","Changed original").put("files",new JSONObject().put("index.html","<h1>Revised source</h1>")));assertThrows(IllegalStateException.class,()->f.agency.verify112(id));assertEquals("completed",f.agency.read(id).getString("status"));}
    }
    @Test public void changedScreenPixelsAndMetadataRefuseFreshEvidenceChecks()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);f.agency.archive112(request(f.agency,id));String frame=f.agency.read(id).getJSONArray("frames").getString(0);Path dir=f.root.resolve("agency-043/screens"),png=dir.resolve(frame+".png"),meta=dir.resolve(frame+".json");byte[] bytes=Files.readAllBytes(png);Files.write(png,new byte[]{1,2,3});assertThrows(IllegalStateException.class,()->f.agency.verify112(id));Files.write(png,bytes);var m=AgentFiles042.loadChecked(meta);var altered=WorldFrames.copy(m).put("taskId",UUID.randomUUID().toString());AgentFiles042.saveChecked(meta,altered);assertThrows(IllegalStateException.class,()->f.agency.verify112(id));AgentFiles042.saveChecked(meta,m);assertTrue(f.agency.verify112(id).getBoolean("passed"));}
    }
    @Test public void preparedSnapshotsWithoutCommitPreserveActiveTasksAndCanBeRetried()throws Exception{
        try(var f=new Agency043Test.Fixture(r->{throw new AssertionError();})){String id=inspect(f);Path checkpoint=f.root.resolve("agency-043/tasks.json");byte[] original=Files.readAllBytes(checkpoint);var data=AgentFiles042.loadChecked(checkpoint);var archive=new ChatArchive112(f.root,f.store,f.learning);var task=data.getJSONArray("tasks").getJSONObject(0);var prepared=archive.prepare(checkpoint,data,Set.of(id),Map.of(id,archive.evidence(task)));assertEquals(0,prepared.getJSONArray("tasks").length());assertEquals(1,f.agency.state().getJSONArray("tasks").length());assertArrayEquals(original,Files.readAllBytes(checkpoint));f.agency=reopen(f);assertEquals(1,f.agency.state().getJSONArray("tasks").length());f.agency.archive112(request(f.agency,id));assertArrayEquals(original,Files.readAllBytes(archive(f,id)));assertTrue(f.agency.verify112(id).getBoolean("passed"));}
    }
}
